	async function getLastTooltipValue(wrapper, htmlEl) {
		tooltipMock.mockClear()
		await wrapper.vm.forceEnableTooltips()

		const filteredCalls = tooltipMock.mock.calls.filter((call) => {
			// only keep calls on wanted node
